// YOUR_AWS_SECRET_KEY_HERE=============
// 🔍 KEYWORD DETECTION ENGINE
// YOUR_AWS_SECRET_KEY_HERE=============
// This code checks if the comment contains the trigger keyword
//
// 📝 CUSTOMIZATION:
// - Modify this to check multiple keywords
// - Add regex patterns for advanced matching
// - Exclude certain phrases
// YOUR_AWS_SECRET_KEY_HERE=============

// Get the comment text from current item
const commentText = $input.first().json.commentText || "";

// Get the keyword from the form submission
const keyword = $('1️⃣ Form: Enter Post Details').first().json['Trigger Keyword'] || "";

// YOUR_AWS_SECRET_KEY_HERE=============
// 🎯 MATCHING LOGIC
// YOUR_AWS_SECRET_KEY_HERE=============
// Case-insensitive matching
// You can modify this for:
// - Exact match: commentText.toLowerCase() === keyword.toLowerCase()
// - Multiple keywords: keywords.some(k => commentText.includes(k))
// - Regex: /pattern/.test(commentText)

const isMatch = commentText.toLowerCase().includes(keyword.toLowerCase());

// YOUR_AWS_SECRET_KEY_HERE=============
// 📤 OUTPUT
// YOUR_AWS_SECRET_KEY_HERE=============
return [
  {
    json: {
      isKeywordMatch: isMatch,
      commentText: commentText,
      searchedKeyword: keyword,
      matchDetails: isMatch ? `Found "${keyword}" in comment` : `No match for "${keyword}"`
    }
  }
];
